pub(crate) fn read8(address: u64) -> Option<u8> {
    let rva = address.checked_sub(super::end_source32a_core::LIB_BASE)?;
    let page = rva & !0xfff;
    let offset = (rva & 0xfff) as usize;
    let table: &[u8; 4096] = match page {
        0x07000 => &PAGE_07000,
        0x3c000 => &PAGE_3C000,
        0x3d000 => &PAGE_3D000,
        _ => return None,
    };
    Some(table[offset])
}
